local config = {
  ui_story_31690401_1_dialog_content = "Ke mana kita mengirimnya, PlayerName?",
  ui_story_31690401_2_dialog_content = "Jika saya tidak salah, kotak besar ini milik <color=#FFB400>kleken</color>.",
  ui_story_31690401_3_dialog_content = "Jadi kita serahkan saja pada Geng Istvan.",
  ui_story_31690401_4_dialog_content = "Bagaimana Anda bisa mengetahuinya? Aku tidak bisa membungkus kepalaku di sekitarnya.",
  ui_story_31690401_5_dialog_content = "Gurita yang tampak jahat tercetak di semua paku yang menyegel kotak berbau Kleken.",
