  ui_story_31690401_22_dialog_content = "Aturan ketiga dari Swashbucklers' Way: <color=#FFB400>Tetap tenang ketika orang lain memuji Anda, jangan sombong!</color>",
  ui_story_31690401_23_dialog_content = "Omong-omong, apa Cara Swashbuckler ini? Jangan berpikir saya pernah mendengar tentang mereka sebelumnya.",
