  ui_story_31690401_25_dialog_content = "Saya membuat aturan sendiri sebagai pengingat tentang bagaimana saya harus bersikap.",
  ui_story_31690401_26_dialog_content = "Karena cita-cita terbesar saya adalah menjadi seorang jagoan sejati.",
  ui_story_31690401_27_dialog_content = "Adapun aturan pertama, itu <color=#FFB400>\"Jangan bertingkah laku dengan cara apa pun yang bertentangan dengan semangat swashbuckling.\"</color>",
