  ui_story_31690401_29_dialog_content = "Karena itu kutipan dari Allura, idolaku.",
  ui_story_31690401_30_dialog_content = "Itu juga karena dia aku ingin menjadi orang yang mandiri dan mandiri.",
  ui_story_31690401_31_dialog_content = "Saya mengatakan itu hanya karena Anda klien pertama saya.",
  ui_story_31690401_32_dialog_content = "Dan akhir-akhir ini, saya mengalami krisis ideologi yang belum pernah terjadi sebelumnya.",
