  ui_story_31690401_34_dialog_content = "Bukankah aku klien pertamamu? Bukankah itu berarti Anda baru saja memulai?",
  ui_story_31690401_35_dialog_content = "Saya menunggu sangat lama bahkan untuk mendapatkan klien!",
  ui_story_31690401_36_dialog_content = "Meskipun krisis yang saya maksud agak terkait dengan itu.",
  ui_story_31690401_37_dialog_content = "Aku selalu mendapatkan pekerjaan melalui wanita di Umbraton.",
  ui_story_31690401_38_dialog_content = "Tapi mereka hanya memberi saya yang mudah.",
  ui_story_31690401_39_dialog_content = "Jika ini terus berlanjut, saya, Super Sadie, tidak akan pernah mencapai apa pun dalam perjalanan saya menuju cita-cita saya.",
  ui_story_31690401_40_dialog_content = "Saya mengerti. Tapi kekuatanmu benar-benar luar biasa, harus kukatakan.",
