  ui_story_31690401_44_dialog_content = "Saya bahkan memaksakan diri untuk membaca buku komik selama tiga hari penuh!",
  ui_story_31690401_45_dialog_content = "(Ya, dia masih anak-anak...)",
  ui_story_31690401_46_dialog_content = "Biar kutebak. Anda mendapat banyak dari itu?",
  ui_story_31690401_47_dialog_content = "Sangat! Protagonis mengatakan bahwa Anda harus memecahkan masalah pada sumbernya.",
  ui_story_31690401_48_dialog_content = "Bagi saya, sumbernya pastilah arti dari semangat swashbuckling!",
  ui_story_31690401_49_dialog_content = "Saya telah meniru wanita yang lebih tua, tetapi tidak pernah merenungkan alasan di balik tindakan mereka.",
  ui_story_31690401_50_dialog_content = "Sekarang saya mengerti bahwa perbedaan di antara kami adalah bahwa mereka tahu arti sebenarnya dari semangat swashbuckling dan saya tidak!",
  ui_story_31690401_51_dialog_content = "Dan karena saya tidak, saya bukan orang yang suka main-main.",
  ui_story_31690401_52_dialog_content = "Aku tidak bisa terus hidup dalam bayang-bayang mereka. Saya harus menemukan semangat swashbuckling saya sendiri!",
