  ui_story_31690401_58_dialog_content = "Untuk menyelesaikan pekerjaan tanpa hambatan untuk membuktikan bahwa Anda benar untuk mempercayai saya.",
  ui_story_31690401_X58_dialog_content = "Baiklah, saatnya untuk bergerak! Ayo pergi, PlayerName.",
