  ui_story_31690401_61_dialog_content = "Saya pikir saya telah mengalami krisis lain, PlayerName.",
  ui_story_31690401_62_dialog_content = "Lihat dua orang licik di belakang toko di gang di sana itu?",
  ui_story_31690401_63_dialog_content = "Ya, mereka tampaknya mengisi karung dengan beberapa benda mengkilap.",
  ui_story_31690401_64_dialog_content = "Itu adalah permata! Mereka mencuri permata dari ruang belakang toko!",
  ui_story_31690401_65_dialog_content = "Tapi, aku…",
  ui_story_31690401_66_dialog_content = "Apakah Anda tidak ingin menjadi seorang swashbuckler? Aturan yang mana lagi?",
  ui_story_31690401_67_dialog_content = "Benar, aturan kedua!",
  ui_story_31690401_68_dialog_content = "Jangan pernah lari ketika seseorang dalam kesulitan, selalu bantulah ketika kamu harus...",
