  ui_story_31690401_76_dialog_content = "Tapi itu dan menegakkan keadilan tidak saling eksklusif.",
  ui_story_31690401_77_dialog_content = "Jika itu saya, saya juga tidak akan tinggal diam.",
  ui_story_31690401_78_dialog_content = "Dan hanya ada dua dari mereka. Ini seharusnya mudah bagi kita.",
