  ui_story_31690401_82_dialog_content = "Jelas bahwa seseorang menyerahkannya. Kami harus menilai kembali situasinya.",
  ui_story_31690401_83_dialog_content = "Maksudmu mereka punya kaki tangan?",
  ui_story_31690401_84_dialog_content = "Hustle, keluarkan lebih banyak barang!",
