  ui_story_31690401_89_dialog_content = "Aku akan masuk untuk melihat barang berharga apa lagi yang ada di sana. Tunggu disini.",
  ui_story_31690401_90_dialog_content = "Ini dia! Tidak ada tempat bagi seorang pengecut dalam pekerjaan ini!",
  ui_story_31690401_91_dialog_content = "Itu membuat setidaknya 2-on-4. Mari kita kembali ke kotak dan membuat rencana.",
  ui_story_31690401_92_dialog_content = "Jangan panik, Sadie... Kamu bisa melakukannya, Sadie...",
  ui_story_31690401_93_dialog_content = "Tidak—saya tidak tahu harus berbuat apa, PlayerName!",
  ui_story_31690401_94_dialog_content = "Tenang saja, Sadi. Kami satu-satunya yang dapat membantu saat ini.",
  ui_story_31690401_95_dialog_content = "Kami kalah jumlah, jadi kami mungkin tidak bisa melawan mereka.",
  ui_story_31690401_96_dialog_content = "Mari kita tenang, menyatukan kepala kita, dan membuat rencana.",
