  ui_story_31690401_99_dialog_content = "Tapi kami tidak punya senjata, dan saya juga tidak tahu cara menggunakannya.",
  ui_story_31690401_100_dialog_content = "Jadi itu tidak akan berhasil. Ada ide lain?",
  ui_story_31690401_101_dialog_content = "Jika Genevieve ada di sini, dia akan memanggil penggemarnya hanya dengan satu kata!",
