  ui_story_31690401_107_dialog_content = "Tapi aku tidak sekuat dia.",
  ui_story_31690401_108_dialog_content = "Saya kira meniru pasukan yang Anda sebut \"wanita Umbraton\" bukanlah pilihan di sini.",
  ui_story_31690401_109_dialog_content = "Mengapa tidak menanganinya dengan cara Anda?",
  ui_story_31690401_110_dialog_content = "Tidakkah Anda ingin menemukan semangat swashbuckling Anda sendiri?",
  ui_story_31690401_111_dialog_content = "Semangat swashbuckling saya sendiri...",
  ui_story_31690401_112_dialog_content = "Oh tidak, mereka akan pergi!",
  ui_story_31690401_113_dialog_content = "Lupakan! Aku harus berjuang. Maksudku, para wanita Umbraton juga selalu terluka!",
  ui_story_31690401_114_dialog_content = "Tidak ada swashbuckler yang hanya akan melihat orang jahat pergi. Ayo, Coolster!",
  ui_story_31690401_115_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_31690401_116_dialog_content = "Astaga! Apa itu tadi? Takut bejesus keluar dari saya!",
  ui_story_31690401_117_dialog_content = "Untungnya, para pencuri melewatkan itu, atau mereka akan pergi sekarang!",
  ui_story_31690401_118_dialog_content = "Saya tidak percaya betapa kuatnya Anda ...",
  ui_story_31690401_119_dialog_content = "Meletakkan pemukul di atas bahu Anda sudah cukup untuk melepaskan paku dari sudut kotak.",
  ui_story_31690401_120_dialog_content = "PlayerName! Lihat, sebuah catatan jatuh darinya!",
  ui_story_31690401_121_dialog_content = "Sayangnya, saya buta huruf.",
  ui_story_31690401_122_dialog_content = "Coba kulihat.",
  ui_story_31690401_123_dialog_content = "Ini dia.",
  ui_story_31690401_124_dialog_content = "Aku ingin tahu apa yang ada di dalam kotak? Biarkan aku memanjat dan melihat...",
  ui_story_31690401_125_dialog_content = "\"Kamu tahu kotak ini milikku dari gurita, kan?\"",
  ui_story_31690401_126_dialog_content = "\"Caelestit yang baik hati sepertimu juga akan mengirimnya kembali ke Umbraton, kan?\"",
  ui_story_31690401_127_dialog_content = "\"Dan saya pikir itu akan dibuka cepat atau lambat.\"",
  ui_story_31690401_128_dialog_content = "\"Kalau begitu, izinkan saya meninggalkan Anda dengan catatan terima kasih ini. —Kleken\"",
  ui_story_31690401_129_dialog_content = "Aduh, Klek! Aku akan mendapatkan Anda untuk ini!",
  ui_story_31690401_130_dialog_content = "Aku tahu apa yang harus dilakukan sekarang, PlayerName! Keadilan akan menang di bawah pengawasan saya!",
  ui_story_31690401_131_dialog_content = "Semua barang berharga dimuat. Ini sudah cukup.",
  ui_story_31690401_132_dialog_content = "Ya, hehe cukup untuk dua kehidupan!",
  ui_story_31690401_133_dialog_content = "Lalu apa yang kita tunggu? Mari kita pergi dari sini!",
  ui_story_31690401_134_dialog_content = "<color=#e8d9bb>Pyur!</color>",
  ui_story_31690401_135_dialog_content = "Ugh—!",
  ui_story_31690401_136_dialog_content = "<color=#e8d9bb>Pyur!</color>",
  ui_story_31690401_137_dialog_content = "Ada apa, pria tinggi? Aduh!",
  ui_story_31690401_138_dialog_content = "<color=#e8d9bb>Cukup, siip!</color>",
  ui_story_31690401_139_dialog_content = "Apakah anak-anak bermain bisbol di belakang gudang lagi? Mereka telah mengirim bola mereka terbang melalui jendela!",
  ui_story_31690401_140_dialog_content = "Dan apa yang dikatakan tentang mereka... <color=#FFB400>666</color>? Anak-anak zaman sekarang!",
  ui_story_31690401_141_dialog_content = "Dan mereka logam padat. Jika mereka menyerang siapa pun—",
  ui_story_31690401_142_dialog_content = "Surga! Empat orang tergeletak di sini di tanah! Aku tahu itu berbahaya!",
  ui_story_31690401_143_dialog_content = "Tunggu, tas-tas ini ada di sini...",
  ui_story_31690401_144_dialog_content = "Bukankah ini semua dari gudang saya? Cara untuk pergi dengan bola!",
  ui_story_31690401_145_dialog_content = "Sebagai bonus untuk menyelesaikan pekerjaan, saya mentraktir Anda es loli!",
  ui_story_31690401_146_dialog_content = "Ini dia.",
  ui_story_31690401_147_dialog_content = "Juga, saya tertarik untuk mengetahui bagaimana Anda mendapatkan ide untuk menaklukkan pencuri.",
  ui_story_31690401_148_dialog_content = "Setelah saya menyenggol tutupnya, saya perhatikan ada hal-hal mengkilap yang terpantul melalui celah.",
  ui_story_31690401_149_dialog_content = "Saya pikir akan ada sesuatu yang berguna di dalam kotak yang begitu besar.",
  ui_story_31690401_150_dialog_content = "Aku selalu bisa percaya pada kekuatanku jika bukan yang lain, kau tahu.",
  ui_story_31690401_151_dialog_content = "Aku naik ke kotak dan memeriksa apa yang ada di dalamnya.",
  ui_story_31690401_152_dialog_content = "Itu penuh dengan bola logam padat! Betapa beruntungnya Super Sadie Swashbuckler 666!",
  ui_story_31690401_153_dialog_content = "Lelucon Kleken akhirnya membantu kami ...",
  ui_story_31690401_154_dialog_content = "Aku bahkan tidak bisa mulai menggambarkan apa yang aku rasakan saat ini.",
  ui_story_31690401_155_dialog_content = "Bola-bola itu langsung mengingatkan saya pada komik yang saya baca tiga hari lalu.",
  ui_story_31690401_156_dialog_content = "Komik?",
  ui_story_31690401_157_dialog_content = "Ya. Di permukaan, protagonisnya adalah penggemar bisbol.",
  ui_story_31690401_158_dialog_content = "Tapi dia benar-benar berubah menjadi petarung ketika tidak ada yang melihat dan mengalahkan Eclipsites dengan bola Lumina.",
  ui_story_31690401_159_dialog_content = "Meskipun saya menemukan cara kali ini, saya tidak sepenuhnya puas dengan hasilnya.",
  ui_story_31690401_160_dialog_content = "Tapi saya pikir ide Anda bagus, dan memukul pencuri dengan presisi seperti itu bukanlah hal yang mudah!",
  ui_story_31690401_161_dialog_content = "Jika peringkat sempurna untuk swashbuckling adalah sepuluh, saya akan memberi Anda dua belas!",
  ui_story_31690401_162_dialog_content = "Betulkah? Itu-",
  ui_story_31690401_163_dialog_content = "Aturan kedua dari Swashbucklers' Way, kan? Anda melakukan pekerjaan dengan baik hari ini dan pantas untuk menepuk punggung Anda sendiri.",
  ui_story_31690401_164_dialog_content = "Saya merasa seperti saya masih meniru orang lain dan tidak melakukan pekerjaan saya sendiri.",
  ui_story_31690401_165_dialog_content = "Tapi setidaknya Anda tidak terburu-buru ke dalam situasi tanpa berpikir seperti teman-teman Anda.",
  ui_story_31690401_166_dialog_content = "Meskipun Anda mendapat inspirasi dari buku komik, Anda tetap menemukan ide yang paling cocok untuk Anda.",
  ui_story_31690401_167_dialog_content = "Anda melindungi orang lain, juga diri Anda sendiri. Saya akan menyebutnya sebagai semangat swashbuckling unik Anda sendiri.",
  ui_story_31690401_168_dialog_content = "Terima kasih, PlayerName. Saya akhirnya tahu apa yang dibutuhkan oleh semangat swashbuckling sekarang!",
  ui_story_31690401_169_dialog_content = "Tetapi saya juga tahu bahwa saya masih memiliki jalan panjang untuk menjadi seorang jagoan sejati.",
  ui_story_31690401_170_dialog_content = "Tapi Super Sadie Swashbuckler 666 tidak menyerah!",
  ui_story_31690401_171_dialog_content = "Anda akan melihat saya lagi ketika saya seorang petualang sejati.",
  ui_story_31690401_172_dialog_content = "Oh, saya sangat menantikan itu.",
  ui_story_31690401_173_dialog_content = "Saya tahu suatu hari Anda akan memiliki semangat swashbuckling Anda sendiri."
